private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        // Duplicate the buffer to avoid changing its position
        ByteBuffer duplicate = bb.duplicate();
        duplicate.flip(); // set limit to current position and position to zero
        int remaining = duplicate.remaining();
        byte[] bytes = new byte[remaining];
        duplicate.get(bytes);

        String decoded = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
        sb.append(decoded);

        // Move the original buffer's position past the bytes we processed
        bb.position(bb.position() + remaining);

        // Return the index of the next unchecked character
        return i + remaining;
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to decode UTF-8 octets", e);
    }
}

