private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null){
        return node;
    }
    TreeNode<T> lt = node.left;
    node.left = lt.right;
    if (lt.right != null){
        lt.right.parent = node;
    }
    lt.right = node;
    lt.parent = node.parent;
    node.parent = lt;
    if (lt.parent != null){
        if (lt.parent.left == node){
            lt.parent.left = lt;
        } else if (lt.parent.right == node){
            lt.parent.right = lt;
        }
    }
    return lt;
}

