@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    try {
        // create left partition vertices
        List<V> left = new ArrayList<>();
        for (int i = 0; i < 2; i++) { // left side size 2
            @SuppressWarnings("unchecked")
            V vertex = (V) new Object();
            target.addVertex(vertex);
            left.add(vertex);
            resultMap.put("L" + i, vertex);
        }
        // create right partition vertices
        List<V> right = new ArrayList<>();
        for (int j = 0; j < 3; j++) { // right side size 3
            @SuppressWarnings("unchecked")
            V vertex = (V) new Object();
            target.addVertex(vertex);
            right.add(vertex);
            resultMap.put("R" + j, vertex);
        }
        // add all possible edges between left and right partitions
        for (V u : left) {
            for (V v : right) {
                @SuppressWarnings("unchecked")
                E edge = (E) new Object();
                target.addEdge(u, v, edge);
            }
        }
