public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || mappings == null) {
        return new Mappings();
    }
    try {
        // Retrieve the current mapping for the given table name.
        Mappings current = this.getMappingForTable(tableName);
        if (current == null) {
            return new Mappings();
        }

        Mappings diff = new Mappings();

        // Iterate over each field in the current mapping.
        for (Map.Entry<?, ?> entry : current.entrySet()) {
            if (!(entry.getKey() instanceof String)) {
                continue;
            }
            String fieldName = (String) entry.getKey();

            // Skip the _source configuration.
            if ("_source".equals(fieldName)) {
                continue;
            }

            // Check if the field already exists in the input (history) mapping.
            boolean existsInHistory = false;
            for (Map.Entry<?, ?> hEntry : mappings.entrySet()) {
                if (!(hEntry.getKey() instanceof String)) {
                    continue;
                }
                if (fieldName.equals(hEntry.getKey())) {
                    existsInHistory = true;
                    break;
                }
            }

            // If the field does not exist in history, add it to the diff.
            if (!existsInHistory) {
                diff.put(fieldName, entry.getValue());
            }
        }

        return diff;
    } catch (Exception e) {
        // In case of any failure, return an empty mapping to avoid errors downstream.
        return new Mappings();
    }
}

