         | ((long)(buf[offset+1] & 0xFF) << 48)
         | ((long)(buf[offset+2] & 0xFF) << 40)
         | ((long)(buf[offset+3] & 0xFF) << 32)
         | ((long)(buf[offset+4] & 0xFF) << 24)
