static long compressTimeBucket(long timeBucket,int dayStep){
    if (timeBucket <= 0 || dayStep <= 0) {
        return timeBucket;
    }
    try {
        int year = (int)(timeBucket / 10000);
        int month = (int)((timeBucket % 10000) / 100);
        int day = (int)(timeBucket % 100);
        int bucketIndex = (day - 1) / dayStep;
        int baseDay = bucketIndex * dayStep + 1;
        // Simple overflow safeguard: ensure baseDay not greater than 31
        if (baseDay > 31) {
            baseDay = 1;
        }
        return year * 10000L + month * 100L + baseDay;
    } catch (Exception e) {
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int start = index;
    if (start < 0) {
        start = 0;
    }
    if (start > str.length()) {
        return 0;
    }
    int remaining = str.length() - start;
    int count = Math.min(len, remaining);
    if (count <= 0) {
        return 0;
    }
    int size = 0;
    int i = 0;
    while (i < count) {
        char c = str.charAt(start + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < count && Character.isLowSurrogate(str.charAt(start + i + 1))) {
            size += 4;
            i++; // skip low surrogate
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

