private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    }
    return str.endsWith(suffix);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading slash for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] rawSegments = path.split("/");
    for (String seg : rawSegments) {
        if (seg.isEmpty()) {
            continue;
        }
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException ex) {
                throw new RuntimeException(ex);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

