public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (shift <= 63) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint");
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int slotsToPop = 0;
    int len = descriptor.length();
    int i = 0;
    try {
        if (len > 0 && descriptor.charAt(0) == '(') {
            // method descriptor: parse argument types until ')'
            i = 1;
            while (i < len && descriptor.charAt(i) != ')') {
                // skip array brackets
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                char c = descriptor.charAt(i);
                if (c == 'L') {
                    // reference type: consume until ';'
                    i = descriptor.indexOf(';', i);
                    if (i == -1) {
                        throw new IllegalArgumentException("invalid descriptor");
                    }
                    i++; // skip ';'
                    slotsToPop += 1;
                } else {
                    // primitive type
                    if (c == 'J' || c == 'D') {
                        slotsToPop += 2;
                    } else {
                        slotsToPop += 1;
                    }
                    i++; // consume the type char
                }
            }
            if (i >= len) {
                throw new IllegalArgumentException("invalid method descriptor");
            }
            // skip the closing ')'
            i++;
            // skip return type descriptor (if any, but it is not popped)
        } else {
            // single type descriptor
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            char c = descriptor.charAt(i);
            if (c == 'L') {
                i = descriptor.indexOf(';', i);
                if (i == -1) {
                    throw new IllegalArgumentException("invalid descriptor");
                }
                i++; // skip ';'
                slotsToPop += 1;
            } else {
                if (c == 'J' || c == 'D') {
                    slotsToPop += 2;
                } else {
                    slotsToPop += 1;
                }
                i++; // consume the type char
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("invalid descriptor", e);
    }
    if (pos < slotsToPop) {
        throw new IllegalStateException("stack underflow");
    }
    pos -= slotsToPop;
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("buffer is null");
    }
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("off "+off+" len "+len+" exceeds buffer length "+b.length);
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        grow(newCount);
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int len = arr.length;
    if (i < 0 || j < 0 || i >= len || j >= len) {
        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

