public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    int len = name.length();
    if (len > 1) {
        char c0 = name.charAt(0);
        char c1 = name.charAt(1);
        if (Character.isUpperCase(c0) && Character.isUpperCase(c1)) {
            return name;
        }
    }
    char first = name.charAt(0);
    if (Character.isLowerCase(first)) {
        return Character.toUpperCase(first) + name.substring(1);
    } else {
        return name;
    }
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Determine the number of bytes written in the current chunk
        int start = current.readPosition();
        int end   = current.writePosition();
        int length = end - start;
        if (length > 0) {
            out.write(current.buffer(), start, length);
            totalSize += length;
        }
        current = current.next();
    }
    return totalSize;
}

