public String format(final LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        // Format timestamp as ISO-8601
        String time = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ").format(new java.util.Date(event.getTimeStamp()));
        // Get level
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
        // Get logger name
        String logger = event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN";
        // Get thread name
        String thread = event.getThreadName() != null ? event.getThreadName() : "UNKNOWN";
        // Rendered message
        String message = event.getRenderedMessage() != null ? event.getRenderedMessage() : "";
        // Build the formatted string
        return String.format("[%s] [%s] [%s] [%s] - %s", time, level, logger, thread, message);
    } catch (Exception e) {
        // In case formatting fails, return empty string
        return "";
    }
}

