public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }
    final int[] PRIMES = {
        3, 7, 13, 23, 43, 79, 163, 331, 673, 1361,
        2729, 5471, 10949, 21911, 43853, 87719, 175447, 350899, 701819, 1403641,
        2807303, 5614657, 11229331, 22458671, 44917381, 89834771, 179669551,
        359339171, 718678363, 1437356723, 2147483647
    };
    int index = java.util.Arrays.binarySearch(PRIMES, desiredCapacity);
    if (index < 0) {
        index = -index - 1;
    }
    if (index >= PRIMES.length) {
        index = PRIMES.length - 1;
    }
    return PRIMES[index];
}

