public void init(){
    try {
        String distPath = getDistPath(); // Assume this method returns the distribution path
        if (distPath == null || distPath.trim().isEmpty()) {
            logger.warn("Dist path is not configured; initialization skipped.");
            return;
        }

        java.io.File distDir = new java.io.File(distPath);
        if (distDir.exists()) {
            if (!distDir.isDirectory()) {
                logger.error(distPath + " exists but is not a directory.");
                throw new IllegalStateException(distPath + " exists but is not a directory.");
            }
            if (!distDir.canWrite()) {
                logger.error("No write permission for dist directory: " + distDir.getAbsolutePath());
                throw new SecurityException("No write permission for dist directory: " + distDir.getAbsolutePath());
            }
            logger.info("Dist directory exists and is writable: " + distDir.getAbsolutePath());
        } else {
            if (distDir.mkdirs()) {
                logger.info("Created dist directory: " + distDir.getAbsolutePath());
            } else {
                logger.error("Unable to create dist directory: " + distDir.getAbsolutePath());
                throw new RuntimeException("Unable to create dist directory: " + distDir.getAbsolutePath());
            }
        }
    } catch (Exception e) {
        logger.error("Failed to initialize configuration.", e);
        throw new RuntimeException("Failed to initialize configuration.", e);
    }
}

