    int len;
    try {
        len = readInt(); // Assume readInt() is defined elsewhere in the class
    } catch (EOFException e) {
        throw new IOException("Unexpected end of stream while reading string length", e);
    }
    if (len < 0) {
        return null; // Interpret negative length as null string
    }
    if (len == 0) {
        return ""; // Empty string
    }
    byte[] bytes = new byte[len];
    int offset = 0;
    while (offset < len) {
        int read = source.read(bytes, offset, len - offset); // Assume 'source' is the InputStream field
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        offset += read;
    }
    try {
