private static int digitValue(final char c) {
    if (c >= '0' && c <= '9') {
        return c - '0';
    } else if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    } else if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    } else {
        return -1;
    }
}

private java.util.Map<java.lang.String,java.lang.Object> buildContent(com.google.gson.JsonObject jsonObject){
    java.util.Map<java.lang.String,java.lang.Object> map = new java.util.HashMap<>();
    if (jsonObject==null){
        return map;
    }
    for (java.util.Map.Entry<java.lang.String,com.google.gson.JsonElement> entry : jsonObject.entrySet()){
        java.lang.String key = entry.getKey();
        com.google.gson.JsonElement element = entry.getValue();
        java.lang.Object value = null;
        if (element==null || element.isJsonNull()){
            value = null;
        } else if (element.isJsonPrimitive()){
            com.google.gson.JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isBoolean()){
                value = prim.getAsBoolean();
            } else if (prim.isNumber()){
                java.lang.Number num = prim.getAsNumber();
                if (num.doubleValue()==num.longValue()){
                    if (num.longValue() <= java.lang.Integer.MAX_VALUE && num.longValue() >= java.lang.Integer.MIN_VALUE){
                        value = java.lang.Integer.valueOf(num.intValue());
                    } else {
                        value = java.lang.Long.valueOf(num.longValue());
                    }
                } else {
                    value = java.lang.Double.valueOf(num.doubleValue());
                }
            } else if (prim.isString()){
                value = prim.getAsString();
            }
        } else if (element.isJsonObject()){
            value = buildContent(element.getAsJsonObject());
        } else if (element.isJsonArray()){
            java.util.List<java.lang.Object> list = new java.util.ArrayList<>();
            for (com.google.gson.JsonElement arrElem : element.getAsJsonArray()){
                if (arrElem.isJsonPrimitive()){
                    com.google.gson.JsonPrimitive prim = arrElem.getAsJsonPrimitive();
                    if (prim.isBoolean()){
                        list.add(prim.getAsBoolean());
                    } else if (prim.isNumber()){
                        java.lang.Number num = prim.getAsNumber();
                        if (num.doubleValue()==num.longValue()){
                            if (num.longValue() <= java.lang.Integer.MAX_VALUE && num.longValue() >= java.lang.Integer.MIN_VALUE){
                                list.add(java.lang.Integer.valueOf(num.intValue()));
                            } else {
                                list.add(java.lang.Long.valueOf(num.longValue()));
                            }
                        } else {
                            list.add(java.lang.Double.valueOf(num.doubleValue()));
                        }
                    } else {
                        list.add(prim.getAsString());
                    }
                } else if (arrElem.isJsonObject()){
                    list.add(buildContent(arrElem.getAsJsonObject()));
                } else {
                    list.add(null);
                }
            }
            value = list;
        }
        map.put(key,value);
    }
    if (jsonObject.has("ats") && !jsonObject.get("ats").isJsonNull()){
        map.put("ats",jsonObject.get("ats"));
    }
    return map;
}

