public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i == len - 1) {
            throw new IllegalArgumentException("String ends with solitary backslash.");
        }
        char next = str.charAt(++i);
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\\':
                sb.append('\\');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\"':
                sb.append('\"');
                break;
            case 'u':
                if (i + 4 >= len) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence in string: " + str);
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    sb.append((char) codePoint);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid hex digits in Unicode escape: " + hex, e);
                }
                i += 4;
                break;
            case 'x':
                // \xNN hex escape, up to 4 hex digits
                int hexStart = i + 1;
                int hexEnd = hexStart;
                while (hexEnd < len && hexEnd < hexStart + 4 && Character.digit(str.charAt(hexEnd), 16) != -1) {
                    hexEnd++;
                }
                if (hexStart == hexEnd) {
                    throw new IllegalArgumentException("Invalid hex escape sequence after \\x in string: " + str);
                }
                String hexVal = str.substring(hexStart, hexEnd);
                try {
                    int val = Integer.parseInt(hexVal, 16);
                    sb.append((char) val);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid hex digits in escape: " + hexVal, e);
                }
                i = hexEnd - 1;
                break;
            default:
                // Unknown escape, keep as literal
                sb.append(next);
                break;
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset){
    if (charset == null){
        return null;
    }
    try {
        java.nio.charset.Charset cs = java.nio.charset.Charset.forName(charset);
        return cs.name();
