protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removedCount++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Handle any unexpected errors
        e.printStackTrace();
    }
    return removedCount;
}

