final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // Determine the offset of the CONSTANT_Utf8 entry in the class file buffer
    int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    if (entryOffset < 0 || entryOffset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // The length of the UTF8 string is a 2-byte value immediately after the tag byte
    int length = (classFileBuffer[entryOffset + 1] & 0xFF) << 8 | (classFileBuffer[entryOffset + 2] & 0xFF);
    if (length > charBuffer.length) {
        throw new IllegalArgumentException(
                "Provided charBuffer too small for UTF-8 entry of length " + length);
    }

    // Copy the string bytes into the char buffer, converting each unsigned byte to a char
    int bytePos = entryOffset + 3;
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) (classFileBuffer[bytePos + i] & 0xFF);
    }

    // Construct and return the resulting string
    return new String(charBuffer, 0, length);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    // Construct a circulator starting at 'start' and in the given direction.
    OuterFaceCirculator circ;
    try {
        circ = new OuterFaceCirculator(start, dir);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to create circulator", e);
    }

    // Walk until the predicate is satisfied or the stop node is reached.
    while (true) {
        Node current = circ.node();
        if (current == null) {
            break; // safety guard against infinite loop
        }
        if (predicate.test(current) || current.equals(stop)) {
            break;
        }
        // Advance in the specified direction
        if (dir > 0) {
            circ = circ.next();
        } else {
            circ = circ.prev();
        }
    }
    return circ;
}

