    if (aObj2 == null) {
        return 1;
    }
    // Try natural ordering if both are of the same class and implement Comparable
    if (aObj1.getClass() == aObj2.getClass() && aObj1 instanceof Comparable<?>) {
        @SuppressWarnings("unchecked")
        Comparable<Object> comp1 = (Comparable<Object>) aObj1;
        try {
            return comp1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // Fall through to string comparison
        }
