protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        return null;
    }
    int n = tour.size();
    if (n == 0) {
        return new GraphPath<>(graph, null, null, new ArrayList<E>());
    }
    // Build a map from source vertex to its outgoing edge in the tour
    Map<V, E> nextMap = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        if (nextMap.containsKey(src)) {
            // Ambiguous: a vertex has more than one outgoing edge in the set
            return null;
        }
        nextMap.put(src, e);
    }
    // Pick a starting edge arbitrarily
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    V current = startVertex;
    List<E> orderedEdges = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        E e = nextMap.get(current);
        if (e == null) {
            // Incomplete tour; cannot determine next edge
            return null;
        }
        orderedEdges.add(e);
        current = graph.getEdgeTarget(e);
    }
    V endVertex = current; // should equal startVertex for a closed tour
    return new GraphPath<>(graph, startVertex, endVertex, orderedEdges);
}

