    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    } else {
        // node was the first element
        first = next;
    }

    if (next != null) {
        next.prev = prev;
    } else {
        // node was the last element
        last = prev;
    }

    // Clean up node's references
    node.prev = null;
    node.next = null;

    if (size > 0) {
        size--;
    }
    return true;
}

