private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int size = bounds.size();
    long total = 0L;
    int[] temp = new int[size];
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("Element at index " + i + " is null");
        }
        total += val;
        temp[i] = (int) total;
    }
    List<Integer> suffix = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        suffix.add(temp[i]);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr,int from,int to){
    if(arr==null){
        throw new NullPointerException("Array cannot be null");
    }
    int len = arr.length;
    if(from < 0 || to >= len){
        throw new IllegalArgumentException("Index out of bounds: from=" + from + ", to=" + to);
    }
    if(from > to){
        throw new IllegalArgumentException("from index cannot be greater than to index: from=" + from + ", to=" + to);
    }
    int left = from;
    int right = to;
    while(left < right){
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list.head == null) {
        return;
    }
    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.elementCount += list.elementCount;
    list.elementCount = 0;
    list.head = null;
    list.tail = null;
}

