private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    TreeSet<Integer> sorted = new TreeSet<>();
    for (K k : keys) {
        try {
            Integer val = (Integer) k;
            sorted.add(val);
        } catch (ClassCastException e) {
            // Key is not an Integer; ignore for sorting
        }
    }
    for (K k : keys) {
        try {
            Integer val = (Integer) k;
            Integer lower = sorted.lower(val);
            bounds.add(lower != null ? lower : Integer.MIN_VALUE);
        } catch (ClassCastException e) {
            bounds.add(null);
        }
    }
    return bounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    try{
        if (descriptor.charAt(0) == '('){
            int i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                int j = i;
                while (j < descriptor.length() && descriptor.charAt(j) == '['){
                    j++;
                }
                if (j >= descriptor.length()){
                    throw new IllegalArgumentException();
                }
                if (descriptor.charAt(j) == 'L'){
                    int semi = descriptor.indexOf(';', j);
                    if (semi == -1){
                        throw new IllegalArgumentException();
                    }
                    j = semi + 1;
                } else {
                    j = j + 1;
                }
                i = j;
                count++;
            }
            // if we reach here descriptor is expected to have ')'
            if (i < descriptor.length() && descriptor.charAt(i) == ')'){
                // nothing else
            } else {
                throw new IllegalArgumentException();
            }
        } else {
            int i = 0;
            while (i < descriptor.length()){
                int j = i;
                while (j < descriptor.length() && descriptor.charAt(j) == '['){
                    j++;
                }
                if (j >= descriptor.length()){
                    throw new IllegalArgumentException();
                }
                if (descriptor.charAt(j) == 'L'){
                    int semi = descriptor.indexOf(';', j);
                    if (semi == -1){
                        throw new IllegalArgumentException();
                    }
                    j = semi + 1;
                } else {
                    j = j + 1;
                }
                i = j;
                count++;
            }
        }
    }catch(StringIndexOutOfBoundsException | IllegalArgumentException e){
        throw new IllegalArgumentException("Malformed descriptor: "+descriptor, e);
    }
    if (pos - count < 0){
        throw new IllegalStateException("Stack underflow while popping descriptor");
    }
    pos -= count;
}

