private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new NullPointerException("keys list is null");
    }
    // Convert keys to integers, validating that each key is an Integer
    java.util.List<Integer> intKeys = new java.util.ArrayList<>(keys.size());
    for (K k : keys) {
        if (k == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException(
                "key is not an Integer: " + k
            );
        }
        intKeys.add((Integer) k);
    }
    // Sort a copy of the integer keys to be able to find upper bounds
    java.util.List<Integer> sorted = new java.util.ArrayList<>(intKeys);
    java.util.Collections.sort(sorted);
    // Build the result list
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K k : keys) {
        int key = (Integer) k;
        int idx = java.util.Collections.binarySearch(sorted, key);
        if (idx < 0) {
            // This should not happen because the key is in the list
            idx = -idx - 1 - 1; // fallback to previous element
        }
        int bound;
        if (idx + 1 < sorted.size()) {
            bound = sorted.get(idx + 1);
        } else {
            bound = sorted.get(sorted.size() - 1);
        }
        bounds.add(bound);
    }
    return bounds;
}

