public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Determine the base directory to which the relative path will be applied
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        baseDir = (lastSlash >= 0) ? path.substring(0, lastSlash + 1) : "";
    }

    // Join the base directory with the relative path
    String joined = baseDir + relativePath;

    // Split the joined path into components and normalize
    String[] parts = joined.split("/");
    java.util.List<java.lang.String> stack = new java.util.ArrayList<>();
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Rebuild the normalized path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append('/');
        }
        result.append(stack.get(i));
    }

    // Preserve leading slash if present in the joined path
    if (joined.startsWith("/") && !result.toString().startsWith("/")) {
        result.insert(0, '/');
    }
    return result.toString();
}

