        return new String[0];
    }
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        // All elements are non-null; cast or convert to String array
        String[] result = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = array[i].toString();
        }
        return result;
    } else {
        // Create a new array without nulls
        String[] result = new String[nonNullCount];
        int j = 0;
        for (Object obj : array) {
            if (obj != null) {
                result[j++] = obj.toString();
            }
        }
        return result;
    }
}

