private void checkIfPackedField() throws IOException {
    // If we've already flagged a packed field, there's nothing more to do.
    if (packed) {
        return;
    }
    // In Protocol Buffers a packed repeated field is encoded with the
    // length‑delimited wire type (value 2).  Only fields that are
    // declared as packed in the descriptor should trigger this flag.
    if (currentFieldDescriptor != null
            && currentFieldDescriptor.isPacked()
            && wireType == 2) { // 2 == WIRETYPE_LENGTH_DELIMITED
        packed = true;
    }
}

