public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IOException("Provided file is null");
    }
    if (!file.exists() || !file.canRead()) {
        throw new IOException("Cannot read file: " + file.getAbsolutePath());
    }

    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line); // Assume a static parse method exists
                if (snapshot != null) {
                    allSnapshots.add(snapshot);
                }
            } catch (Exception e) {
                // Skip malformed lines; log if necessary
                // e.printStackTrace();
            }
        }
    }

    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long ts = snapshot.getTimestamp(); // Assume this method exists
        boolean inRange = false;
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) continue;
            long start = range.getStartTime(); // Assume getters exist
            long end = range.getEndTime();
            if (ts >= start && ts <= end) {
                inRange = true;
                break;
            }
        }
        if (inRange) {
            result.add(snapshot);
        }
    }
    return result;
}
